-- Bulk import of 23 real Goa attractions (from Attaractions List - Sheet1.csv)
-- Run this in the Supabase SQL Editor.

-- Schema migration: the attractions table needs an image array for the
-- slider instead of the single placeholder image_url column.
alter table public.attractions drop column if exists image_url;
alter table public.attractions add column if not exists image_urls text[] not null default '{}';

delete from public.attractions where slug = 'aguada-fort'; -- superseded placeholder test row


